import datetime, random

def solve_my(year, month, day):
    day_names = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday']
    t = [0,3,2,5,0,3,5,1,4,6,2,4]
    y = year
    if month < 3:
        y -= 1
    w = (y + y//4 - y//100 + y//400 + t[month-1] + day) % 7
    return day_names[w]

def solve_dt(y,m,d):
    return datetime.date(y,m,d).strftime('%A')

for _ in range(1000):
    y = random.randint(1900,2100)
    m = random.randint(1,12)
    # get days in month
    import calendar
    d = random.randint(1, calendar.monthrange(y,m)[1])
    if solve_my(y,m,d) != solve_dt(y,m,d):
        print('mismatch', y,m,d, solve_my(y,m,d), solve_dt(y,m,d))
        break
else:
    print('all ok')

