def solve(grid):
    """Count islands in a (possibly jagged) 2D grid.
    An island is a group of cells with value 1 connected 4-directionally.
    The grid may contain rows of varying lengths; rows that are empty are ignored.
    """
    if not grid:
        return 0
    rows = len(grid)
    visited = set()
    def dfs(r, c):
        stack = [(r, c)]
        while stack:
            i, j = stack.pop()
            if (i, j) in visited:
                continue
            # bounds check for jagged rows
            if i < 0 or i >= rows:
                continue
            if j < 0 or j >= len(grid[i]):
                continue
            if grid[i][j] != 1:
                continue
            visited.add((i, j))
            stack.append((i-1, j))
            stack.append((i+1, j))
            stack.append((i, j-1))
            stack.append((i, j+1))
    count = 0
    for i in range(rows):
        for j in range(len(grid[i])):
            if grid[i][j] == 1 and (i, j) not in visited:
                count += 1
                dfs(i, j)
    return count

