def solve(nums):
    """Return the length of the longest strictly increasing subsequence.
    Uses O(n^2) DP for simplicity and correctness on all inputs.
    """
    if not nums:
        return 0
    n = len(nums)
    dp = [1] * n  # dp[i] = LIS ending at i
    for i in range(n):
        for j in range(i):
            if nums[j] < nums[i] and dp[j] + 1 > dp[i]:
                dp[i] = dp[j] + 1
    return max(dp)

def solve(n: int, b: int) -> str:
    """Convert integer n to its representation in base b (2 <= b <= 36).
    Uses digits 0-9 and lowercase a-z. Negative numbers get a leading '-'.
    """
    if b < 2 or b > 36:
        raise ValueError("Base out of supported range")
    if n == 0:
        return "0"
    digits = "0123456789abcdefghijklmnopqrstuvwxyz"
    neg = n < 0
    n = -n if neg else n
    res = []
    while n > 0:
        n, rem = divmod(n, b)
        res.append(digits[rem])
    if neg:
        res.append('-')
    return ''.join(reversed(res))

