def solve(n, edges):
    """Return lexicographically smallest topological ordering of n nodes (0..n-1).
    edges list of [a,b] meaning a->b. If cycle, return [] .
    """
    adj = [[] for _ in range(n)]
    indeg = [0]*n
    for a,b in edges:
        if a<0 or a>=n or b<0 or b>=n:
