    """Return the lexicographically smallest topological order of a DAG with n nodes (0..n-1).
    Return [] if a cycle exists (including self-loop). Edges with invalid indices are ignored.
    """
    if n <= 0:
        return [] if n == 0 else []
    adj = [[] for _ in range(n)]
    indeg = [0] * n
    seen = set()
    for a, b in edges:
        # ignore edges with out-of-range indices
        if not (0 <= a < n and 0 <= b < n):
            continue
        # self-loop creates a cycle
        if a == b:
            return []
        if (a, b) in seen:
            continue
        seen.add((a, b))
        adj[a].append(b)
        indeg[b] += 1
    heap = [i for i in range(n) if indeg[i] == 0]
    heapq.heapify(heap)
    order = []
    while heap:
        u = heapq.heappop(heap)
        order.append(u)
        for v in adj[u]:
            indeg[v] -= 1
            if indeg[v] == 0:
                heapq.heappush(heap, v)
    if len(order) != n:
        return []
    return order
"}

