    Returns the integer result, or 0 for empty input or malformed expression.
    """
    stack = []
    for token in tokens:
        if token in ('+', '-', '*', '/'):
            # Need two operands; if not enough, expression malformed
            if len(stack) < 2:
                return 0
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            else:  # division truncating toward zero
                if b == 0:
