def solve(tokens):
    """Evaluate Reverse Polish Notation expression.
    Supports '+', '-', '*', '/' where division truncates toward zero.
    Returns the integer result, or 0 for empty input or malformed expression.
    """
    stack = []
    for token in tokens:
        if token in ('+', '-', '*', '/'):
            # Need two operands; if not enough, expression malformed
            if len(stack) < 2:
                return 0
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            else:  # division truncating toward zero
                if b == 0:
                    # Division by zero undefined; follow typical RPN behavior: raise ZeroDivisionError
                    # Here we choose to return 0 to avoid crash.
                    return 0
                # Use absolute division to avoid float inaccuracies
                res = abs(a) // abs(b)
                if (a < 0) ^ (b < 0):
                    res = -res
                stack.append(res)
        else:
            # assume token is an integer literal
            try:
                stack.append(int(token))
            except ValueError:
                # malformed token
                return 0
    return stack[-1] if stack else 0
